import{_ as e,c as t,o as a,ah as p,ao as s,ap as n}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"Ни один воробей не забыт — его никогда не оставляли без внимания","description":"Иисус сказал, что ни один воробей не падает без воли Отца. Что Матфей и Псалмы говорят о Божьей заботе о животных.","frontmatter":{"title":"Ни один воробей не забыт — его никогда не оставляли без внимания","description":"Иисус сказал, что ни один воробей не падает без воли Отца. Что Матфей и Псалмы говорят о Божьей заботе о животных."},"headers":[],"relativePath":"ru/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"ru/pets-in-heaven/not-one-sparrow-forgotten.md"}'),r={name:"ru/pets-in-heaven/not-one-sparrow-forgotten.md"};function i(l,o,c,h,u,d){return a(),t("div",null,[...o[0]||(o[0]=[p('<div class="pl-quote"><p>«Он был просто маленьким животным. Мир его запомнит? Или только я?»</p><p class="pl-quote-soft">Иисус однажды ответил на этот вопрос, и Его ответ мягче, чем мы ожидаем.</p></div><section class="pl-section"><h2>1. Иисус сказал: ни один воробей не падает без Отца</h2><blockquote><p><strong>Матфея 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>Во времена Иисуса воробьи были одной из самых дешёвых вещей на рынке — два за мелкую монету. Это была жизнь, которую никто особенно не замечал.</p><p>И Иисус сказал: <strong>без воли вашего Отца ни один из них не упадёт на землю.</strong></p><p>Слово «упадёт» здесь означает смерть. Иисус говорит: смерть самой дешёвой птички — не случайность, о которой Бог не знает. Их уход виден. Он записан.</p><p>Если ваш друг был маленьким, из тех, о ком мир говорит «просто животное», — этот стих написан для вас. Бог помнит воробьёв. Он не забудет вашего.</p></section><section class="pl-section"><h2>2. Он кормил его — ни один день не был пропущен</h2><blockquote><p><strong>Псалом 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>Давид также писал:</p><blockquote><p><strong>Псалом 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>«Человека и животное» — в оригинале это слово охватывает и диких, и домашних животных. Бог ставит животных в Свой список тех, кого хранит, — не между делом, а рядом с нами.</p><p>Что это значит? Что от первого до последнего дня — каждая еда, каждая зима, каждый час, когда вас не было дома, — Бог смотрел за ним. Вам казалось, что вы заботитесь о нём один. Вы заботились о нём вместе с Богом.</p></section><section class="pl-section"><h2>3. Он принадлежит Богу — и это самое безопасное место</h2><blockquote><p><strong>Псалом 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>Бог говорит: «Мой — всякий зверь в лесу. Скот на тысяче холмов. Я знаю всех птиц на горах».</p><p>Ваш питомец никогда не был вашей собственностью. Он был даром, который Бог доверил вашей заботе. А когда Дающий забирает дар, Он не выбрасывает его — Он <strong>берёт его домой, к Себе</strong>.</p><p>Вы не знаете, как Он заботится о нём сейчас, где он и помнит ли ваш голос. Но вы знаете, в чьих он руках: в руках, которые сосчитали воробьёв.</p><p class="pl-quote-soft">Если сегодня вы сможете удержать только одну фразу, пусть это будет эта:</p></section><div class="pl-quote"><p>«Он никогда не выходил из поля зрения Бога. И сейчас тоже.»</p></div><section class="pl-section"><h2>Молитва, которую можно попробовать</h2><p>«Господи, спасибо, что доверил его мне на эти годы.<br>Спасибо, что хранил его там, где я не мог видеть.<br>Я больше не могу держать его на руках, но знаю, что Твои руки больше моих.<br>Прошу, позаботься о нём, как Ты заботишься о каждом воробье.<br>И позаботься обо мне, потому что я очень скучаю. Аминь.»</p><p><a href="/ru/pets-in-heaven/">← Вернуться к Pets in Heaven</a> ｜ Далее: <a href="/ru/pets-in-heaven/rainbow-bridge-covenant">По ту сторону Радужного моста</a></p></section><div class="pl-cta"><h2>У него есть имя.</h2><p>Напишите его имя и одну маленькую привычку, о которой знали только вы. Эти детали стоит сохранить.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Скачать в App Store</a></div><div class="pl-bible"><h3>Пусть слово Писания остаётся с вами</h3><p>Все стихи в этой статье — из Библии. С приложением Rainbow Bible вы можете читать Писание в любое время и настроить виджет со стихом дня — небольшой свет для дней, когда вы скучаете.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Виджет Rainbow Bible со стихом 2 Тимофею 2:13" loading="lazy"><figcaption>Стих дня на главном экране</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible — тема «Питомцы на небесах» со стихом Матфея 10:29-31" loading="lazy"><figcaption>Читайте Писание в теме «Питомцы на небесах»</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Скачать Rainbow Bible в App Store</a></div>',8)])])}const b=e(r,[["render",i]]);export{g as __pageData,b as default};
